cd "$(git rev-parse --show-toplevel)" && node -e "
const fs=require('fs');
const raw=fs.readFileSync('package.json','utf8');
// detect duplicate keys in scripts block
const lines=raw.split('\n');
const seen={},dups=[];
let inScripts=false;
lines.forEach((l,i)=>{
  if(/^\s*\"scripts\"\s*:\s*\{/.test(l)){inScripts=true;return;}
  if(inScripts&&/^\s*\}/.test(l)){inScripts=false;return;}
  if(inScripts){const m=l.match(/^\s*\"([^\"]+)\"\s*:/); if(m){if(seen[m[1]])dups.push(m[1]+' (lines '+seen[m[1]]+','+(i+1)+')'); else seen[m[1]]=i+1;}}
});
console.log('DUPLICATE SCRIPT KEYS:', dups.length?dups.join('  |  '):'none');
console.log('JSON.parse:', (()=>{try{JSON.parse(raw);return 'ok (last-wins silently)';}catch(e){return 'FAIL '+e.message}})());
"

